// Adaptive assessment — Track D#3.
//
// Responsibility: decide WHICH difficulty level (1–4) a learner should practise
// at, from stored evidence only, and how that level moves while they work
// through a quiz. Nothing here calls a language model, a vector store, or a
// random number generator, so the same learner state always yields the same
// level. Question *text* is generated by quizService (A17); scoring is
// grading.js (A18); the numbers themselves are learner.js (A18).
//
// Every number is imported, never retyped:
//   * the 1–4 scale and its labels          → learner.js `LEVELS`
//   * the frozen mastery bounds 0.4/0.6/0.8 → learner.js `LEVEL_THRESHOLDS`
//   * the mastery → level mapping           → learner.js `levelFor`
//   * the persisted level for a topic       → learner.js `getTopicMastery` /
//                                             `summarizeMastery` /
//                                             `updateMasteryLevel`
// The 1–4 level is NOT the shipped easy|medium|hard scale; the bridge between
// them is `difficultyForLevel`, also from learner.js.
//
// HONESTY — the rule this module exists to protect: a topic with no graded
// evidence is UNASSESSED (`level: null`, `levelLabel: "unassessed"`), never
// level 1. Level 1 is a measurement ("scored below 40% on real questions");
// level null is "we have not measured this yet". Serving an adaptive question
// for a guessed level would tell a student they are weak at something they
// have never been tested on.
//
// Two defects from docs/HANDOFF.md are deliberately guarded here:
//   * A18: `mastery` is the difficulty-weighted, recency-decayed accuracy
//     learner.js computes (Track D#4), not the naive correct/total. The plain
//     ratio is still reported separately as `correct` / `total` / `percent`.
//   * A20: `learner.js#levelFor` coerces with `Number(mastery)`, and
//     `Number(null) === 0` is finite, so a literal null returns level 1. The
//     guard below is the caller-side coercion learner.js asks for.

import {
  LEVELS,
  LEVEL_THRESHOLDS,
  applyAttempt,
  chooseDifficulty,
  difficultyForLevel,
  getTopicMastery,
  levelFor,
  levelLabel,
  needsRevision,
  summarizeMastery,
  updateMasteryLevel,
} from './learner.js';
import { gradeAnswers } from './grading.js';
import { maybeRecordRecovery, recordEvent, recordStudyEvent } from './events.js';
import { logActivity, nowIso } from '../store/sqlite.js';

// ---------- the 1–4 scale (derived from the frozen table) -------------------

// One level per frozen mastery boundary, plus level 1 for everything below
// them. Derived so the ceiling can never drift from LEVEL_THRESHOLDS.
const MIN_LEVEL = 1;
const MAX_LEVEL = LEVEL_THRESHOLDS.length + 1;

function normalizeTopic(topic) {
  return typeof topic === 'string' ? topic.trim().toLowerCase() : '';
}

/** Four decimals on the wire — the same precision the quiz route reports. */
function round4(value) {
  if (value === null || value === undefined || !Number.isFinite(Number(value))) return null;
  return Number(Number(value).toFixed(4));
}

/**
 * mastery → level with the A20 guard applied.
 *
 * learner.js#levelFor documents that the null coercion belongs to its caller:
 * `Number(null)` is 0, so an unguarded null comes back as level 1 — precisely
 * the "unassessed reported as foundation" defect the 1–4 scale must not have.
 */
function levelOf(mastery) {
  if (mastery === null || mastery === undefined) return null;
  return levelFor(mastery);
}

// ---------- level selection (deterministic) ---------------------------------

/**
 * Decide the level for one adaptive quiz request.
 *
 * An explicit `level` (already validated 1–4 by the route) is used verbatim —
 * the caller is taking over, e.g. to continue a session at the level the
 * in-session sequencing rule reached. Otherwise the learner model decides from
 * stored evidence, which may honestly be "no evidence yet".
 *
 * @returns {{level: number|null, levelLabel: string, difficulty: string,
 *   hasEvidence?: boolean, masteryPercent?: number|null}}
 *   `difficulty` is the practice difficulty to generate with: the level's own
 *   contract difficulty when evidence exists, else the neutral default
 *   `POST /api/quiz/generate` has always used for a topic with no attempts.
 */
export async function resolveLevel(db, { userId, topic, level = null } = {}) {
  if (typeof level === 'number') {
    return { level, levelLabel: levelLabel(level), difficulty: difficultyForLevel(level) };
  }
  const record = await getTopicMastery(db, { userId, topic });
  // Re-derive the level from the stored mastery rather than trusting a cached
  // row: the persisted level and LEVEL_THRESHOLDS must agree, and recomputing
  // means a stale row can never serve a wrong level.
  const chosen = levelOf(record.mastery);
  return {
    level: chosen,
    levelLabel: levelLabel(chosen),
    difficulty: chosen === null ? chooseDifficulty(null) : difficultyForLevel(chosen),
    hasEvidence: record.hasEvidence,
    masteryPercent: record.masteryPercent,
  };
}

// ---------- adaptive sequencing (the in-session rule) -----------------------
//
// ADAPTIVE SEQUENCING RULE — deterministic. It is the only thing that moves
// the difficulty level inside a session. No randomness, no model, no average:
//
//   1. A session starts at the level its quiz was served at.
//   2. The graded answers are replayed in question order. For each answer:
//        correct → runCorrect += 1, runWrong = 0
//        wrong   → runWrong += 1, runCorrect = 0
//      The two runs are never both non-zero: one answer clears the other.
//   3. runCorrect reaches STREAK_TO_SHIFT → level + 1, then both runs reset.
//      runWrong reaches STREAK_TO_SHIFT → level − 1, then both runs reset.
//   4. The level is clamped to 1–4. Every other outcome leaves it unchanged.
//
// STREAK_TO_SHIFT = 2 means "two right answers in a row earn a step up, two
// wrong answers in a row earn a step down". A single lucky or unlucky answer
// can never move the level, because it only clears the opposite run.

const STREAK_TO_SHIFT = 2;

// ---------- the in-session level run (shared by the write and the replay) ----

/**
 * Replay one session's graded answers and report how the level moved.
 *
 * `startLevel` is recovered from the practice difficulty stored on the quiz's
 * `quizzes` row (easy|medium|hard), read from the frozen LEVELS table so the
 * easy→1 / medium→3 / hard→4 mapping has exactly one source.
 *
 * KNOWN LIMITATION (filed in docs/HANDOFF.md): the `quizzes` row stores only the
 * three-word practice difficulty, and BOTH level 1 and level 2 practise "easy".
 * An easy quiz therefore starts its in-session run at level 1, the low end of
 * the band the stored row can prove — the rule still moves correctly from
 * there, but the first step is one level below a level-2 quiz's true start.
 * A `level` column on `quizzes` (schema v9) would remove the ambiguity; the
 * band itself is never wrong, because it comes from the stored row.
 *
 * @returns {{startLevel: number, practiceDifficulty: string, streakToShift: number,
 *   finalLevel: number,
 *   steps: Array<{index:number, correct:boolean, levelBefore:number, levelAfter:number}>}}
 *   `finalLevel` is the level the next question in the session would be served
 *   at, which the client can pin on the next `POST /adaptive/generate`.
 */
function adaptationFor(quiz, perQuestion) {
  const match = Object.keys(LEVELS).find((key) => LEVELS[key].difficulty === quiz.difficulty);
  const served = match === undefined ? 3 : Number(match);
  // Clamp the start to 1–4; a non-numeric start (a corrupt row) falls to the floor.
  const startValue = Number(served);
  const startLevel = Number.isFinite(startValue)
    ? Math.min(MAX_LEVEL, Math.max(MIN_LEVEL, Math.round(startValue)))
    : MIN_LEVEL;
  let level = startLevel;
  let runCorrect = 0;
  let runWrong = 0;
  const steps = perQuestion.map((question, index) => {
    const correct = question.correct === true;
    const levelBefore = level;
    if (correct) {
      runCorrect += 1;
      runWrong = 0;
    } else {
      runWrong += 1;
      runCorrect = 0;
    }
    if (runCorrect >= STREAK_TO_SHIFT) {
      level = Math.min(MAX_LEVEL, level + 1);
      runCorrect = 0;
      runWrong = 0;
    } else if (runWrong >= STREAK_TO_SHIFT) {
      level = Math.max(MIN_LEVEL, level - 1);
      runCorrect = 0;
      runWrong = 0;
    }
    return { index, correct, levelBefore, levelAfter: level };
  });
  return {
    startLevel,
    practiceDifficulty: quiz.difficulty ?? null,
    streakToShift: STREAK_TO_SHIFT,
    steps,
    finalLevel: level,
  };
}

// ---------- one adaptive attempt (shared by the write and the replay) -------

async function loadQuizQuestions(db, quizId) {
  return db.all('SELECT * FROM quiz_questions WHERE quiz_id = ? ORDER BY idx', quizId);
}

// Whole-percent score — the same rounding every quiz endpoint reports.
function percentOf(correct, total) {
  return Math.round((correct / total) * 100);
}

/**
 * Observed evidence for one graded attempt (server-side only; never read by the
 * level maths as history). `masteryBefore` null means the very first attempt.
 */
async function recordAttemptEvidence(db, {
  topicKey, userId, quizId, perQuestion, correct, total, percent, masteryBefore, masteryAfter,
}) {
  for (const item of perQuestion) {
    await recordEvent(db, {
      kind: item.correct ? 'quiz_item_correct' : 'quiz_item_incorrect',
      topic: topicKey,
      detail: { index: item.index, correct: item.correct },
      userId,
    });
  }
  await recordEvent(db, {
    kind: 'quiz_result',
    topic: topicKey,
    detail: { quizId, correct, total, masteryBefore, masteryAfter, percent },
    userId,
  });
  // Recovery check (M5): mastery improved while an approach change is still open.
  if (masteryBefore !== null) {
    await maybeRecordRecovery(db, { topic: topicKey, masteryBefore, masteryAfter, userId });
  }
}

// ---------- recording one attempt ------------------------------------------

/**
 * Grade a full adaptive attempt, update the learner model once, and report the
 * level transition. Deterministic end to end: the same stored questions and
 * the same answers always produce the same result.
 *
 * Mirrors the emit sites of routes/quiz.js so one answered quiz looks the same
 * in the activity feed whichever endpoint recorded it (the legacy `quiz` row +
 * the `quiz_answered` study-history row is the documented duplication A14 and
 * A17 filed for A40; the progress page merges the pair).
 *
 * @returns {object} `result` — the wire payload, persisted verbatim on the
 *   attempt row so a resubmission replays it byte-identically.
 */
export async function recordAdaptiveAttempt(db, { userId, quiz, answers }) {
  const questions = await loadQuizQuestions(db, quiz.id);
  // Deterministic grading — string comparison against the stored key, no AI.
  const { correct, total, perQuestion } = gradeAnswers(questions, answers);
  const percent = percentOf(correct, total);

  const topicKey = normalizeTopic(quiz.topic);
  const topicStats = await db.get('SELECT * FROM learner_topics WHERE topic = ? AND user_id = ?', topicKey, userId);
  const stats = applyAttempt(topicKey, topicStats, { correct, total });

  const now = nowIso();
  // Composite PK on both engines is (user_id, topic); the insert and the
  // conflict target both carry the verified user id.
  await db.run(`
    INSERT INTO learner_topics (user_id, topic, correct, total, difficulty, updated_at, last_practiced_at)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT (user_id, topic) DO UPDATE SET
      correct = excluded.correct, total = excluded.total,
      difficulty = excluded.difficulty, updated_at = excluded.updated_at,
      last_practiced_at = excluded.last_practiced_at
  `, userId, stats.topic, stats.correct, stats.total, stats.difficulty, now, now);

  const masteryAfter = Number(stats.mastery.toFixed(4));
  await recordAttemptEvidence(db, {
    topicKey, userId, quizId: quiz.id, perQuestion, correct, total, percent,
    masteryBefore: stats.before, masteryAfter,
  });

  // The attempt row must exist before the level is recomputed: the learner
  // model reads its evidence through quiz_attempts → quizzes → quiz_questions.
  // result_json is filled in below, once the level transition is known.
  await db.batch([
    {
      sql: 'INSERT INTO quiz_attempts (quiz_id, user_id, answers_json, correct, total, created_at, result_json) VALUES (?, ?, ?, ?, ?, ?, ?)',
      args: [quiz.id, userId, JSON.stringify(answers), correct, total, now, null],
    },
    { sql: 'UPDATE quizzes SET answered_at = ? WHERE id = ? AND user_id = ?', args: [now, quiz.id, userId] },
  ], 'write');

  // Deterministic mastery → level 1-4 (A18's learner.js): refreshes
  // `difficulty_levels` and emits the `level_changed` study event itself, so
  // this module must NOT emit it again.
  let levelUpdate = null;
  let levelFailed = false;
  try {
    levelUpdate = await updateMasteryLevel(db, { userId, topic: topicKey });
  } catch (err) {
    // The attempt is already recorded and graded, so a learner-model failure
    // must not turn a successful submission into a 500 the client would retry.
    // The stored evidence is unchanged, so the next attempt recomputes the
    // same level (self-healing); the in-session rule below needs no database.
    levelFailed = true;
    console.error(`[adaptive] level update failed for user ${userId} topic "${topicKey}":`, err?.message ?? err);
  }

  const adaptation = adaptationFor(quiz, perQuestion);

  const result = {
    score: { correct, total, percent },
    questions: perQuestion,
    levelUpdate: levelUpdate === null ? null : {
      topic: levelUpdate.topic,
      // `null` before the topic's first graded attempt (contract: masteryBefore null).
      beforeLevel: levelUpdate.before.level,
      afterLevel: levelUpdate.after.level,
      masteryBefore: round4(levelUpdate.before.mastery),
      masteryAfter: round4(levelUpdate.after.mastery),
    },
    recommendedLevel: levelUpdate?.after.level ?? adaptation.finalLevel,
    adaptation,
    // Present only on the degraded path above, so a client can say "your level
    // was not refreshed" instead of silently showing a stale number.
    ...(levelFailed ? { levelUpdateFailed: true } : {}),
  };

  // Persist the final result so a repeated submission replays it byte-identically.
  await db.run('UPDATE quiz_attempts SET result_json = ? WHERE quiz_id = ? AND user_id = ?',
    JSON.stringify(result), quiz.id, userId);

  await logActivity(db, 'quiz', quiz.topic, `${correct}/${total} correct (${percent}%)`, quiz.session_id, userId);
  await recordStudyEvent(db, {
    type: 'quiz_answered',
    topic: topicKey,
    detail: `${correct}/${total} correct (${percent}%)`,
    sessionId: quiz.session_id ?? null,
    userId,
  });

  return result;
}

/**
 * Rebuild a result payload for a stored attempt (the 409 replay path) when the
 * attempt row carries no `result_json`. Only reachable for a row written by an
 * older build: the pre-attempt state cannot be reconstructed after the fact, so
 * `beforeLevel` / `masteryBefore` are reported as `null` rather than invented.
 */
export async function replayAdaptiveResult(db, { quiz, answersJson, userId }) {
  const questions = await loadQuizQuestions(db, quiz.id);
  let answers = [];
  try {
    const parsed = JSON.parse(answersJson ?? '[]');
    answers = Array.isArray(parsed) ? parsed : [];
  } catch {
    answers = [];
  }
  const { correct, total, perQuestion } = gradeAnswers(questions, answers);
  const current = await getTopicMastery(db, { userId, topic: quiz.topic });
  const level = levelOf(current.mastery);
  return {
    score: { correct, total, percent: percentOf(correct, total) },
    questions: perQuestion,
    levelUpdate: {
      topic: current.topic,
      beforeLevel: null,
      afterLevel: level,
      masteryBefore: null,
      masteryAfter: round4(current.mastery),
    },
    recommendedLevel: level,
    adaptation: adaptationFor(quiz, perQuestion),
  };
}

// ---------- the read-only roll-up ------------------------------------------

// One roll-up row: an assessed topic passes its measured values; an unassessed
// one (a generated-but-unanswered quiz) passes nulls, so it is reported as level
// `null` — never as level 1, which would count a measurement never taken.
function topicEntry({ topic, masteryPercent, level, correct, total, lastPracticedAt }) {
  return {
    topic,
    masteryPercent,
    level,
    levelLabel: levelLabel(level),
    difficulty: level === null ? chooseDifficulty(null) : difficultyForLevel(level),
    correct,
    total,
    needsRevision: total > 0 ? needsRevision({ correct, total }) : false,
    lastPracticedAt,
  };
}

/**
 * Per-topic mastery rolled up to a level — the `GET /api/adaptive/progress`
 * payload. Read-only: no AI, no vector call, no writes.
 *
 * Assessed topics come from `difficulty_levels` (A18's `summarizeMastery`) and
 * are joined with the plain `learner_topics` counts. Topics the learner has
 * generated a quiz for but never answered are listed AFTER the assessed ones as
 * `unassessed` — they are real engagement, and hiding them would make "no
 * evidence yet" invisible. They are not counted in `levelCounts`, because
 * counting an unmeasured topic as level 1 is the exact bug this endpoint must
 * not have.
 */
export async function adaptiveProgress(db, { userId }) {
  const summary = await summarizeMastery(db, { userId });
  const statsRows = await db.all('SELECT * FROM learner_topics WHERE user_id = ?', userId);
  const statsByTopic = new Map(statsRows.map((row) => [row.topic, row]));

  const topics = summary.topics.map((item) => {
    const stats = statsByTopic.get(item.topic);
    const correct = Number(stats?.correct) || 0;
    const total = Number(stats?.total) || 0;
    return topicEntry({
      topic: item.topic,
      masteryPercent: item.masteryPercent,
      level: levelOf(item.mastery),
      correct,
      total,
      lastPracticedAt: stats?.last_practiced_at ?? item.lastAssessedAt ?? null,
    });
  });

  const seen = new Set(topics.map((entry) => entry.topic));
  const pending = await db.all(
    `SELECT topic, MAX(created_at) AS created_at FROM quizzes
     WHERE user_id = ? AND answered_at IS NULL
     GROUP BY topic ORDER BY MAX(created_at) DESC`,
    userId,
  );
  for (const row of pending) {
    const key = normalizeTopic(row.topic);
    if (key === '' || seen.has(key)) continue;
    seen.add(key);
    topics.push(topicEntry({
      topic: key, masteryPercent: null, level: null, correct: 0, total: 0, lastPracticedAt: null,
    }));
  }

  const attempts = await db.all('SELECT correct, total FROM quiz_attempts WHERE user_id = ?', userId);
  const questionsAnswered = attempts.reduce((sum, attempt) => sum + (Number(attempt.total) || 0), 0);
  const correctAnswers = attempts.reduce((sum, attempt) => sum + (Number(attempt.correct) || 0), 0);

  return {
    topics,
    overall: {
      quizzesTaken: attempts.length,
      questionsAnswered,
      // The contract's "zeroed overall" for an empty account. As A28 flagged
      // for /api/learner/progress, 0 means both "nothing measured" and
      // "0% correct" here; questionsAnswered is the disambiguating field.
      accuracyPercent: questionsAnswered > 0 ? Math.round((correctAnswers / questionsAnswered) * 100) : 0,
    },
    levelCounts: summary.levelCounts,
  };
}
